defs.About:
/** What `about` answers, in native ids. */
type About = {
  /** The network's word for it: "Group", "Server", "Room", "Channel", "Community". */
  noun?: string;
  fields: AboutFields;
  members?: {
    list: AboutMember[];
    /** How many there are; list may hold fewer (Discord servers load members lazily). */
    total?: number;
    complete: boolean;
  };
  /** Adding people here, for an adapter with 'addMembers'. Left out where nobody adds people (DMs, servers, channels). */
  adding?: AboutAdding;
  roles?: AboutRole[];
  rules?: AboutRule[];
  /** This account's own standing here. */
  you?: { role?: string; rank?: number };
  invite?: AboutInvite;
  pinned?: AboutPinned;
  /** Read-only details only some networks have: "Room version", "Verification level", "Created". */
  facts?: { label: string; value: string }[];
};

defs.AboutAdding:
/** Adding people to a group (capability 'addMembers', the `addMembers` command): whether this account may here, and */
type AboutAdding = {
  /** This account may add people here now. */
  can: boolean;
  /** Why not, in words. When it may, a limit worth knowing ("Only your friends", "Up to 10 people in all"). */
  reason?: string;
  who: AddWho;
  /** add: they are in at once. invite: they get an invite and are in once they accept (Matrix). */
  mode: "add" | "invite";
  /** How many more fit, when the network caps the group (Discord: 10 people in all). */
  room?: number;
};

defs.AboutChange:
/** One change. `invite` makes, replaces or turns off the invite link; `pin` pins or unpins a message. */
type AboutChange = { key: "history"; value: HistoryVisibility }
| { key: "addMembers"; value: Who }
| { key: "name"; value: string }
| { key: "topic"; value: string }
| { key: "avatar"; value: string }
| { key: "disappearing"; value: number }
| { key: "slowMode"; value: number }
| { key: "nsfw"; value: boolean }
| { key: "announceOnly"; value: boolean }
| { key: "editInfo"; value: Who }
| { key: "joinApproval"; value: boolean }
| { key: "joinRule"; value: JoinRule }
| { key: "encrypted"; value: boolean }
| { key: "invite"; op: "create" | "revoke" }
| { key: "pin"; message: string; remove?: boolean };

defs.AboutFields:
type AboutFields = {
  history?: AboutSetting;
  addMembers?: AboutSetting;
  name?: AboutSetting;
  topic?: AboutSetting;
  avatar?: AboutSetting;
  disappearing?: AboutSetting;
  slowMode?: AboutSetting;
  nsfw?: AboutSetting;
  announceOnly?: AboutSetting;
  editInfo?: AboutSetting;
  joinApproval?: AboutSetting;
  joinRule?: AboutSetting;
  encrypted?: AboutSetting;
};

defs.AboutInvite:
type AboutInvite = {
  /** The link, when there is one and this account may see it. */
  link: null | string;
  /** Make one, or a new one in place of the old (which stops working). */
  canCreate: boolean;
  /** Turn the link off. */
  canRevoke?: boolean;
  reason?: string;
  /** A Matrix address (alias) or room id, which works as a link without anyone making one. */
  derived?: boolean;
};

defs.AboutMember:
type AboutMember = {
  /** Native identity id. The adapter emits identity facts for members first. */
  id: string;
  /** What the network calls their standing: "Admin", "Owner", "Moderator", the top Discord role. */
  role?: string;
  /** Power, to sort by: 100 for admins and owners, 50 for moderators, 0 for members. Matrix: the power level. */
  rank?: number;
  /** CSS colour of their role (Discord). */
  color?: string;
};

defs.AboutPinned:
type AboutPinned = {
  /** Native message ids, newest pin first. */
  messages: string[];
  canEdit: boolean;
  reason?: string;
};

defs.AboutRole:
type AboutRole = {
  id: string;
  name: string;
  color?: string;
  rank: number;
  /** Members with it, when known. */
  count?: number;
};

defs.AboutRule:
/** "Who can do what", in words: one row per thing the network gates. */
type AboutRule = {
  what: string;
  who: string;
  /** This account may. */
  you: boolean;
};

defs.AboutSetting:
/** One setting: its value, and whether this account may change it. */
type AboutSetting<K extends AboutKey = AboutKey> = {
  /** null: the network has it but did not say. */
  value: null | import("@dither-chat/protocol").AboutValues[K];
  canEdit: boolean;
  /** Why not, in words (shown on hover and under the setting). Also a limit worth knowing when canEdit is true. */
  reason?: string;
};

defs.AddRef:
/** What a pasted or typed thing could be. parseAdd gives every reading; the hub asks a fitting account to resolve one. */
type AddRef = { kind: "invite"; network: Network; code: string; url: string }
| { kind: "place"; network: Network; address: string; via?: string[] }
| { kind: "name"; network: Network; name: string }
| { kind: "person"; network: Network; handle: string };

defs.AttachmentFact:
type AttachmentFact = {
  nativeId?: string;
  kind: AttachmentKind;
  mime?: string;
  name?: string;
  size?: number;
  width?: number;
  height?: number;
  url: string;
};

defs.CallParticipant:
type CallParticipant = {
  /** Native user id. */
  id: string;
  muted: boolean;
  deafened: boolean;
  speaking: boolean;
  video?: boolean;
};

defs.ConversationFact:
type ConversationFact = {
  /** Discord channel snowflake | Matrix room id | Matrix thread "<roomId>|<rootEventId>" | Signal group "group:<base64 id>" | Signal 1:1 "dm:<selfAci>:<peerAci>" */
  nativeId: string;
  shape: Shape;
  variant?: "rules" | "media" | "text" | "announcement" | "forum" | "voice" | "stage" | "feed";
  /** Omit for directs: the UI names them after the peer. */
  name?: string;
  topic?: string;
  avatarUrl?: string;
  encrypted?: boolean;
  archived?: boolean;
  /** Threads: the conversation they hang off. */
  parentConversation?: string;
  /** Containing spaces (a graph: a Matrix room may be in several). */
  spaces?: SpaceRef[];
  /** Identity native IDs. Only for direct, group and self; big channels skip this. */
  participants?: string[];
  mute?: NativeMute;
  lastMessageAt?: number;
};

defs.ForwardFact:
/** Where a forwarded message came from, as far as the network says. Discord names the channel, message and */
type ForwardFact = {
  conversation?: string;
  message?: string;
  /** The original's community, when the conversation alone does not say (a Discord guild id). */
  space?: string;
  author?: string;
  authorName?: string;
  ts?: number;
};

defs.IdentityFact:
type IdentityFact = {
  nativeId: string;
  handle?: string;
  displayName?: string;
  avatarUrl?: string;
  isBot?: boolean;
  isSelf?: boolean;
  /** In the address book / friends list. Contacts get a Person, strangers in big channels do not. */
  contact?: boolean;
};

defs.MemberFact:
/** Someone seen as a member of a space. The identity fact for `who` is emitted first. */
type MemberFact = {
  /** Native identity id. */
  who: string;
  /** ms epoch: when they joined the space, where the network says. */
  joinedAt?: number;
  /** Role names in the space. */
  roles?: string[];
  /** Their nickname in the space. */
  nick?: string;
};

defs.MentionablePerson:
type MentionablePerson = {
  /** Native identity id, as `<@nativeId>` in a body. */
  nativeId: string;
  name: string;
  handle?: string;
  avatar?: string;
  isBot?: boolean;
  /** ms of their last message in this conversation, when the adapter knows it. */
  lastSpoke?: number;
};

defs.MentionableRole:
/** A role that may be pinged here (Discord: a mentionable role, or any role while you have Mention Everyone). */
type MentionableRole = {
  id: string;
  name: string;
  /** #RRGGBB */
  color?: string;
  count?: number;
};

defs.MessageFact:
/** Canonical message body: a Discord-flavoured Markdown subset. */
type MessageFact = {
  /** Discord snowflake | Matrix event id | Signal "<authorAci>:<sentTimestamp>" */
  nativeId: string;
  conversation: string;
  author: string;
  ts: number;
  editedTs?: number;
  kind?: "call" | "encrypted" | "media" | "text" | "system" | "sticker";
  body: string;
  replyTo?: string;
  /** This message is the root of that thread conversation. */
  threadRoot?: string;
  mentionsSelf?: boolean;
  /** With mentionsSelf: the mention was */
  mentionsAll?: boolean;
  attachments?: AttachmentFact[];
  /** Full reaction snapshot (backfill). Live changes use the `reaction` event. */
  reactions?: ReactionFact[];
  /** This message forwards another, as the network marks it. body and attachments are the forwarded content. */
  forward?: ForwardFact;
  extra?: Record<string, unknown>;
};

defs.NativeMute:
type NativeMute = {
  level?: "all" | "mentions" | "none";
  /** ms epoch; muted until then. */
  until?: number;
};

defs.NetworkQuery:
/** What a network search asks for, from the hub's query language (search.ts) in the network's terms. */
type NetworkQuery = {
  /** Words and phrases as typed ("quoted" kept), without operators. */
  text: string;
  /** Native identity ids. */
  authors?: string[];
  mentions?: string[];
  /** Native conversation ids, inside a space scope. */
  in?: string[];
  has?: string[];
  /** ms, inclusive and exclusive as search.ts. */
  after?: number;
  before?: number;
  sort?: "newest" | "oldest" | "relevance";
};

defs.PersonAbout:
/** What a network says about one person (the `profile` command, docs/profile.md), in native ids. Only what the */
type PersonAbout = {
  /** As the network has them now. The adapter also emits an identity fact with these. */
  displayName?: string;
  handle?: string;
  avatar?: string;
  /** A banner picture (Discord). */
  banner?: string;
  /** A CSS colour for the banner when there is no picture (Discord's accent colour). */
  accent?: string;
  /** Bio or About text, as the network has it (Discord markdown, WhatsApp About, Signal About). */
  bio?: string;
  /** A short status line with an emoji (Discord custom status, Signal's About emoji). */
  status?: { text?: string; emoji?: string };
  pronouns?: string;
  /** ms epoch: when their account was made (Discord, from the id). */
  createdAt?: number;
  /** Your standing with them on this network. */
  relationship?: "friend" | "requested" | "requesting" | "blocked" | "contact" | "following" | "stranger";
  /** Spaces you share, native ids, with their name and roles there. All of them, not only where they posted. */
  mutualSpaces?: { id: string; nick?: string; roles?: { name: string; color?: string }[]; joinedAt?: number }[];
